set-header.value:
@{
				string accessKey = (string)context.Variables["awsAccessKey"];
				string secretKey = (string)context.Variables["awsSecretKey"];
				string sessionToken = (string)context.Variables["awsSessionToken"];
				string region = (string)context.Variables["awsRegion"];
				string service = (string)context.Variables["awsService"];
				string datetime = (string)context.Variables["awsDateTime"];
				string date = datetime.Substring(0, 8);
				string host = (string)context.Variables["awsHost"];
				string path = (string)context.Variables["awsPath"];
				string canonicalPath = string.Join("/", path.Split('/').Select(segment => Uri.EscapeDataString(segment)));
				byte[] payload = context.Request.Body == null ? new byte[0] : context.Request.Body.As<byte[]>(preserveContent: true);

				using (var sha = System.Security.Cryptography.SHA256.Create()) {
					string payloadHash = BitConverter.ToString(sha.ComputeHash(payload)).Replace("-", "").ToLowerInvariant();
					string canonicalHeaders = "content-type:application/json\nhost:" + host + "\nx-amz-date:" + datetime + "\n";
					string signedHeaders = "content-type;host;x-amz-date";
					if (!string.IsNullOrEmpty(sessionToken)) {
						canonicalHeaders += "x-amz-security-token:" + sessionToken + "\n";
						signedHeaders += ";x-amz-security-token";
					}
					string canonicalRequest = string.Join("\n", "POST", canonicalPath, "", canonicalHeaders, signedHeaders, payloadHash);
					string credentialScope = date + "/" + region + "/" + service + "/aws4_request";
					string canonicalRequestHash = BitConverter.ToString(sha.ComputeHash(Encoding.UTF8.GetBytes(canonicalRequest))).Replace("-", "").ToLowerInvariant();
					string stringToSign = string.Join("\n", "AWS4-HMAC-SHA256", datetime, credentialScope, canonicalRequestHash);

					byte[] dateKey;
					using (var hmac = new System.Security.Cryptography.HMACSHA256(Encoding.UTF8.GetBytes("AWS4" + secretKey))) {
						dateKey = hmac.ComputeHash(Encoding.UTF8.GetBytes(date));
					}
					byte[] regionKey;
					using (var hmac = new System.Security.Cryptography.HMACSHA256(dateKey)) {
						regionKey = hmac.ComputeHash(Encoding.UTF8.GetBytes(region));
					}
					byte[] serviceKey;
					using (var hmac = new System.Security.Cryptography.HMACSHA256(regionKey)) {
						serviceKey = hmac.ComputeHash(Encoding.UTF8.GetBytes(service));
					}
					byte[] signingKey;
					using (var hmac = new System.Security.Cryptography.HMACSHA256(serviceKey)) {
						signingKey = hmac.ComputeHash(Encoding.UTF8.GetBytes("aws4_request"));
					}
					using (var hmac = new System.Security.Cryptography.HMACSHA256(signingKey)) {
						string signature = BitConverter.ToString(hmac.ComputeHash(Encoding.UTF8.GetBytes(stringToSign))).Replace("-", "").ToLowerInvariant();
						return "AWS4-HMAC-SHA256 Credential=" + accessKey + "/" + credentialScope + ", SignedHeaders=" + signedHeaders + ", Signature=" + signature;
					}
				}
			}
